1	/**
2	 * sensor-replay.js - 多传感器场景回放引擎
3	 *
4	 * 为加速度计、陀螺仪、心率、气压计提供同步的确定性 mock 数据。
5	 * 每种传感器的数据物理意义一致，便于端侧特征提取和决策树推理。
6	 */
7	
8	var SAMPLE_INTERVAL_MS = 80
9	
10	var SCENARIOS = [
11	  { id: "normal", title: "日常步行", subtitle: "低风险基线", samples: 40 },
12	  { id: "run", title: "正常跑步", subtitle: "验证不误报", samples: 44 },
13	  { id: "shake", title: "剧烈晃动", subtitle: "冲击但持续运动", samples: 44 },
14	  { id: "fall", title: "疑似跌倒", subtitle: "失重·冲击·静止", samples: 48 },
15	  { id: "immobility", title: "异常静止", subtitle: "长时间低活动", samples: 56 }
16	]
17	
18	// ─── 基础振荡函数 ──────────────────────────────────────
19	
20	function oscillation(index, speed) {
21	  return Math.sin(index * speed)
22	}
23	
24	// ─── 加速度计场景数据 ──────────────────────────────────
25	
26	function normalSample(index) {
27	  return {
28	    x: 0.08 * oscillation(index, 0.7),
29	    y: 0.06 * oscillation(index, 0.43),
30	    z: 1 + 0.08 * oscillation(index, 0.9)
31	  }
32	}
33	
34	function runSample(index) {
35	  return {
36	    x: 0.3 * oscillation(index, 1.1),
37	    y: 0.18 * oscillation(index, 0.73),
38	    z: 1.05 + 0.72 * oscillation(index, 1.45)
39	  }
40	}
41	
42	function shakeSample(index) {
43	  if (index === 12) {
44	    return { x: 2.6, y: 1.7, z: 1.4 }
45	  }
46	  return {
47	    x: 0.8 * oscillation(index, 1.9),
48	    y: 0.65 * oscillation(index, 1.2),
49	    z: 1 + 0.55 * oscillation(index, 1.55)
50	  }
51	}
52	
53	function fallSample(index) {
54	  if (index < 13) {
55	    return normalSample(index)
56	  }
57	  if (index === 13) {
58	    return { x: 0.08, y: 0.05, z: 0.18 }
59	  }
60	  if (index === 14) {
61	    return { x: 2.9, y: 1.7, z: 1.3 }
62	  }
63	  if (index < 21) {
64	    var decay = (21 - index) / 7
65	    return {
66	      x: 0.96 + 0.25 * decay * oscillation(index, 1.4),
67	      y: 0.08 * decay,
68	      z: 0.2 + 0.3 * decay
69	    }
70	  }
71	  return {
72	    x: 0.97 + 0.004 * oscillation(index, 0.5),
73	    y: 0.03,
74	    z: 0.18 + 0.004 * oscillation(index, 0.8)
75	  }
76	}
77	
78	function immobilitySample(index) {
79	  if (index < 6) {
80	    return { x: 0.03 + index * 0.002, y: 0.02, z: 0.99 }
81	  }
82	  return {
83	    x: 0.025 + 0.002 * oscillation(index, 0.31),
84	    y: 0.018 + 0.001 * oscillation(index, 0.47),
85	    z: 0.999 + 0.002 * oscillation(index, 0.27)
86	  }
87	}
