241	export function createReplayEngine(callbacks) {
242	  var timer = null
243	
244	  function stop() {
245	    if (timer) {
246	      clearInterval(timer)
247	      timer = null
248	    }
249	  }
250	
251	  function start(scenarioId) {
252	    stop()
253	    var definition = SCENARIOS[0]
254	    for (var i = 0; i < SCENARIOS.length; i++) {
255	      if (SCENARIOS[i].id === scenarioId) {
256	        definition = SCENARIOS[i]
257	        break
258	      }
259	    }
260	
261	    var sampleIndex = 0
262	    if (callbacks.onStart) {
263	      callbacks.onStart(definition)
264	    }
265	
266	    timer = setInterval(function () {
267	      var sample = makeSample(definition.id, sampleIndex)
268	      if (callbacks.onSample) {
269	        callbacks.onSample(sample, sampleIndex + 1, definition.samples)
270	      }
271	      sampleIndex += 1
272	
273	      if (sampleIndex >= definition.samples) {
274	        stop()
275	        if (callbacks.onComplete) {
276	          callbacks.onComplete(definition)
277	        }
278	      }
279	    }, SAMPLE_INTERVAL_MS)
280	  }
281	
282	  return { start: start, stop: stop }
283	}
